<?php
namespace App\Console\Commands;
use App\Models\Budget; use App\Models\Bill; use App\Models\FinancialAnomaly; use App\Models\FinancialGoal; use App\Models\JiraGeneratedAchievement; use App\Models\RecurringExpense; use App\Models\User; use App\Services\NotificationService; use Carbon\CarbonImmutable; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB;
class CheckInAppNotifications extends Command {
    protected $signature='notifications:check'; protected $description='Create idempotent in-app alerts for budgets, bills, balances, anomalous spending, goals, and achievement drafts';
    public function handle(NotificationService $notifications): int { $today=CarbonImmutable::today(); foreach(User::query()->select('id')->cursor() as $user){ $this->budgets($user->id,$today,$notifications); $this->recurring($user->id,$today,$notifications); $this->bills($user->id,$today,$notifications); $this->lowBalances($user->id,$notifications); $this->anomalies($user->id,$notifications); $this->goals($user->id,$today,$notifications); $this->drafts($user->id,$today,$notifications); } return self::SUCCESS; }
    private function budgets(int $userId,CarbonImmutable $today,NotificationService $n): void { foreach(Budget::query()->where('user_id',$userId)->with('category')->cursor() as $budget){ [$start,$end]=$budget->period_type==='weekly'?[$today->startOfWeek(),$today->endOfWeek()]:[$today->startOfMonth(),$today->endOfMonth()]; $spent=(float)DB::table('transactions')->where('user_id',$userId)->where('category_id',$budget->category_id)->whereIn('type',['EXPENSE','RECURRING'])->whereBetween('transaction_date',[$start->toDateString(),$end->toDateString()])->sum('amount'); $percent=$budget->amount>0?($spent/(float)$budget->amount)*100:0; foreach([100,80,50] as $threshold) if($percent >= $threshold) { $n->create($userId,'budget_threshold',"{$threshold}% budget used",($budget->category?->name ?? 'Category')." has used ".round($percent,1)."% of its {$budget->period_type} budget.","budget:{$budget->id}:{$start->toDateString()}:{$threshold}",['budget_id'=>$budget->id,'threshold'=>$threshold,'percent'=>round($percent,1)],'/budgets'); break; } } }
    private function recurring(int $userId,CarbonImmutable $today,NotificationService $n): void { RecurringExpense::query()->where('user_id',$userId)->where('is_active',true)->whereDate('next_run_date','<=',$today)->each(fn($row)=>$n->create($userId,'recurring_due','Recurring expense due',"{$row->title} is due to run.","recurring:{$row->id}:{$row->next_run_date?->toDateString()}",['recurring_expense_id'=>$row->id],'/recurring-expenses')); }
    private function bills(int $userId,CarbonImmutable $today,NotificationService $n): void { Bill::where('user_id',$userId)->where('is_active',true)->whereNull('paid_at')->whereDate('due_date','<=',$today->addDays(3))->each(fn($b)=>$n->create($userId,'recurring_due','Bill payment due',"{$b->name} is due on {$b->due_date->toDateString()}.","bill:{$b->id}:{$b->due_date->toDateString()}",['bill_id'=>$b->id],'/bills')); }
    private function lowBalances(int $userId,NotificationService $n): void { DB::table('accounts')->where('user_id',$userId)->whereNotNull('low_balance_threshold')->whereColumn('current_balance','<=','low_balance_threshold')->each(fn($a)=>$n->create($userId,'financial_anomaly','Low account balance',"{$a->name} is below its configured balance threshold.","low-balance:{$a->id}",['account_id'=>$a->id],'/accounts')); }
    private function anomalies(int $userId,NotificationService $n): void { $rows=DB::table('transactions')->where('user_id',$userId)->whereNotNull('category_id')->whereIn('type',['EXPENSE','RECURRING'])->latest('id')->limit(200)->get(); $baselines=DB::table('transactions')->where('user_id',$userId)->whereNotNull('category_id')->whereIn('type',['EXPENSE','RECURRING'])->groupBy('category_id')->selectRaw('category_id, AVG(amount) as baseline')->pluck('baseline','category_id'); foreach($rows as $row){$base=(float)($baselines[$row->category_id] ?? 0); if($base>0 && (float)$row->amount >= $base*2){$a=FinancialAnomaly::firstOrCreate(['user_id'=>$userId,'transaction_id'=>$row->id,'type'=>'spend_spike'],['title'=>'Unusual expense detected','message'=>'This expense is at least twice the historical category average.','amount'=>$row->amount,'baseline_amount'=>$base,'detected_at'=>now()]);$n->create($userId,'financial_anomaly',$a->title,$a->message,"anomaly:{$a->id}",['anomaly_id'=>$a->id],'/financial-intelligence');}} }
    private function goals(int $userId,CarbonImmutable $today,NotificationService $n): void { FinancialGoal::query()->where('user_id',$userId)->whereNotNull('target_date')->whereDate('target_date','>=',$today)->each(function($goal)use($userId,$today,$n){ $start=CarbonImmutable::parse($goal->created_at)->startOfDay(); $end=$goal->target_date; $days=max($start->diffInDays($end),1); $elapsed=max($start->diffInDays($today),0); $expected=((float)$goal->target_amount)*min($elapsed/$days,1); if((float)$goal->current_saved_amount < $expected) $n->create($userId,'goal_behind','Savings goal needs attention',"{$goal->name} is behind its expected contribution pace.","goal:{$goal->id}:{$today->format('Y-m')}",['goal_id'=>$goal->id],'/financial-goals'); }); }
    private function drafts(int $userId,CarbonImmutable $today,NotificationService $n): void { $count=JiraGeneratedAchievement::query()->where('user_id',$userId)->where('status','draft')->count(); if($count) $n->create($userId,'achievement_review','Achievement drafts awaiting review',"You have {$count} Jira-generated achievement draft".($count===1?'':'s')." awaiting review.","achievement-drafts:{$today->toDateString()}:{$count}",['count'=>$count],'/achievements'); }
}
